{"command":"python3 - << 'PY'
import os, time
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

N = 60000*1024
key = os.urandom(16); nonce = os.urandom(12); pt = os.urandom(N); aad = os.urandom(32)

def run_ctx():
    enc = Cipher(algorithms.AES(key), modes.GCM(nonce)).encryptor()
    enc.authenticate_additional_data(aad)
    ct = enc.update(pt) + enc.finalize()
    return ct, enc.tag

def run_aead():
    ct = AESGCM(key).encrypt(nonce, pt, aad)
    return ct[:-16], ct[-16:]

run_ctx(); run_aead()
for name, fn in [('ctx', run_ctx), ('aead', run_aead)]:
    t0 = time.perf_counter()
    for _ in range(5):
        fn()
    print(name, (time.perf_counter()-t0)/5*1000, 'ms')

# empty aad vs none
def run_aead_none():
    return AESGCM(key).encrypt(nonce, pt, None)
run_aead_none()
t0 = time.perf_counter()
for _ in range(5):
    run_aead_none()
print('aead none', (time.perf_counter()-t0)/5*1000)

def run_aead_empty():
    return AESGCM(key).encrypt(nonce, pt, b'')
run_aead_empty()
t0 = time.perf_counter()
for _ in range(5):
    run_aead_empty()
print('aead empty', (time.perf_counter()-t0)/5*1000)

# Does the reference pass associated_data which may be b'' ?
print('aad lens vary')
PY"}

