#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <wmmintrin.h>
#include <emmintrin.h>
#include <smmintrin.h>

static __m128i key_schedule[11];

static inline __m128i aes128_assist(__m128i t1, __m128i t2) {
    __m128i t3;
    t2 = _mm_shuffle_epi32(t2, 0xff);
    t3 = _mm_slli_si128(t1, 0x4);
    t1 = _mm_xor_si128(t1, t3);
    t3 = _mm_slli_si128(t3, 0x4);
    t1 = _mm_xor_si128(t1, t3);
    t3 = _mm_slli_si128(t3, 0x4);
    t1 = _mm_xor_si128(t1, t3);
    t1 = _mm_xor_si128(t1, t2);
    return t1;
}

static void aes128_set_key(const uint8_t *key) {
    __m128i t1, t2;
    t1 = _mm_loadu_si128((const __m128i*)key);
    key_schedule[0] = t1;
    t2 = _mm_aeskeygenassist_si128(t1, 0x01); key_schedule[1] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x02); key_schedule[2] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x04); key_schedule[3] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x08); key_schedule[4] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x10); key_schedule[5] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x20); key_schedule[6] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x40); key_schedule[7] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x80); key_schedule[8] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x1b); key_schedule[9] = t1 = aes128_assist(t1, t2);
    t2 = _mm_aeskeygenassist_si128(t1, 0x36); key_schedule[10] = t1 = aes128_assist(t1, t2);
}

typedef struct { uint8_t *out; size_t start_block; size_t nblocks; } job_t;

static void aes_ctr8_range(uint8_t *out, size_t start, size_t nblocks) {
    __m128i c = _mm_set_epi64x(0, (long long)start);
    const __m128i one = _mm_set_epi64x(0, 1);
    size_t i = 0;
    uint8_t *base = out + start*16;
    for (; i + 8 <= nblocks; i += 8) {
        __m128i b0=c; c=_mm_add_epi64(c, one);
        __m128i b1=c; c=_mm_add_epi64(c, one);
        __m128i b2=c; c=_mm_add_epi64(c, one);
        __m128i b3=c; c=_mm_add_epi64(c, one);
        __m128i b4=c; c=_mm_add_epi64(c, one);
        __m128i b5=c; c=_mm_add_epi64(c, one);
        __m128i b6=c; c=_mm_add_epi64(c, one);
        __m128i b7=c; c=_mm_add_epi64(c, one);
        b0=_mm_xor_si128(b0, key_schedule[0]); b1=_mm_xor_si128(b1, key_schedule[0]);
        b2=_mm_xor_si128(b2, key_schedule[0]); b3=_mm_xor_si128(b3, key_schedule[0]);
        b4=_mm_xor_si128(b4, key_schedule[0]); b5=_mm_xor_si128(b5, key_schedule[0]);
        b6=_mm_xor_si128(b6, key_schedule[0]); b7=_mm_xor_si128(b7, key_schedule[0]);
        for (int r = 1; r < 10; r++) {
            __m128i k = key_schedule[r];
            b0=_mm_aesenc_si128(b0,k); b1=_mm_aesenc_si128(b1,k);
            b2=_mm_aesenc_si128(b2,k); b3=_mm_aesenc_si128(b3,k);
            b4=_mm_aesenc_si128(b4,k); b5=_mm_aesenc_si128(b5,k);
            b6=_mm_aesenc_si128(b6,k); b7=_mm_aesenc_si128(b7,k);
        }
        __m128i k = key_schedule[10];
        b0=_mm_aesenclast_si128(b0,k); b1=_mm_aesenclast_si128(b1,k);
        b2=_mm_aesenclast_si128(b2,k); b3=_mm_aesenclast_si128(b3,k);
        b4=_mm_aesenclast_si128(b4,k); b5=_mm_aesenclast_si128(b5,k);
        b6=_mm_aesenclast_si128(b6,k); b7=_mm_aesenclast_si128(b7,k);
        _mm_storeu_si128((__m128i*)(base + (i+0)*16), b0);
        _mm_storeu_si128((__m128i*)(base + (i+1)*16), b1);
        _mm_storeu_si128((__m128i*)(base + (i+2)*16), b2);
        _mm_storeu_si128((__m128i*)(base + (i+3)*16), b3);
        _mm_storeu_si128((__m128i*)(base + (i+4)*16), b4);
        _mm_storeu_si128((__m128i*)(base + (i+5)*16), b5);
        _mm_storeu_si128((__m128i*)(base + (i+6)*16), b6);
        _mm_storeu_si128((__m128i*)(base + (i+7)*16), b7);
    }
}

static void *worker(void *arg) {
    job_t *j = arg;
    aes_ctr8_range(j->out, j->start_block, j->nblocks);
    return NULL;
}

int main() {
    uint8_t key[16] = {0};
    aes128_set_key(key);
    size_t N = 60000*1024;
    size_t nblocks = N/16;
    uint8_t *out = aligned_alloc(64, N);
    int K = 6;
    pthread_t th[16];
    job_t jobs[16];
    size_t per = (nblocks / K) & ~7ULL;
    /* warmup */
    for (int k = 0; k < K; k++) {
        jobs[k].out = out;
        jobs[k].start_block = k * per;
        jobs[k].nblocks = (k == K-1) ? (nblocks - k*per) : per;
        pthread_create(&th[k], NULL, worker, &jobs[k]);
    }
    for (int k = 0; k < K; k++) pthread_join(th[k], NULL);

    int iters = 5;
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int i = 0; i < iters; i++) {
        for (int k = 0; k < K; k++) pthread_create(&th[k], NULL, worker, &jobs[k]);
        for (int k = 0; k < K; k++) pthread_join(th[k], NULL);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("AES-CTR %d threads (incl create/join) 60MB: %.2f ms\n", K, dt/iters*1000);
    return 0;
}
EOF
