    __m128i t = _mm_slli_epi64(c, 57);
    __m128i t2 = _mm_slli_epi64(c, 62);
    __m128i t3 = _mm_slli_epi64(c, 63);
    t = _mm_xor_si128(t, _mm_xor_si128(t2, t3));
    __m128i t_lo = _mm_slli_si128(t, 8);
    __m128i t_hi = _mm_srli_si128(t, 8);
