typedef struct {
    const uint8_t *pt;
    uint8_t *ct;
    size_t start_block, nblocks;
    __m128i ctr0;       /* big-endian counter block for block index start_block, as xmm */
    __m128i ghash_acc;  /* partial GHASH accumulator (byte-swapped domain) */
    int do_ghash;
} job_t;

static const __m128i one = {0,0}; /* filled at runtime */

static inline __m128i be_add(__m128i ctr, uint64_t add) {
    /* ctr is a big-endian counter block loaded natively. Increment its low 32 bits (big endian). */
    return ctr; /* placeholder, we pass precomputed */
}

static void ctr_blocks(job_t *j) {
    const __m128i bswap = _mm_loadu_si128((const __m128i*)BSWAP);
    __m128i ctr = j->ctr0;
    const __m128i inc = _mm_set_epi32(0, 0, 0, 1); /* added after bswap */
    __m128i acc = _mm_setzero_si128();
    const uint8_t *pt = j->pt + j->start_block * 16;
    uint8_t *ct = j->ct + j->start_block * 16;
    size_t n = j->nblocks;
    __m128i ctr_le = _mm_shuffle_epi8(ctr, bswap);
    for (size_t i = 0; i < n; i++) {
        __m128i cb = _mm_shuffle_epi8(ctr_le, bswap);
        __m128i b = _mm_xor_si128(cb, ks[0]);
        for (int r = 1; r < 10; r++) b = _mm_aesenc_si128(b, ks[r]);
        b = _mm_aesenclast_si128(b, ks[10]);
        __m128i p = _mm_loadu_si128((const __m128i*)(pt + i*16));
        __m128i c = _mm_xor_si128(b, p);
        _mm_storeu_si128((__m128i*)(ct + i*16), c);
        ctr_le = _mm_add_epi32(ctr_le, inc);
        if (j->do_ghash) {
            acc = _mm_xor_si128(acc, _mm_shuffle_epi8(c, bswap));
            acc = gmul(acc);
        }
    }
    j->ghash_acc = acc;
}

typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int cmd; /* 0 idle, 1 work, 2 exit */
    job_t job;
} worker_t;

static worker_t workers[MAX_THREADS];

static void *worker_fn(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd == 0) pthread_cond_wait(&w->cv, &w->mu);
        if (w->cmd == 2) { pthread_mutex_unlock(&w->mu); return NULL; }
        pthread_mutex_unlock(&w->mu);
        ctr_blocks(&w->job);
        pthread_mutex_lock(&w->mu);
        w->cmd = 0;
        pthread_cond_signal(&w->cv);
    }
}

static void pool_init(void) {
    for (int i = 0; i < nthreads; i++) {
        pthread_mutex_init(&workers[i].mu, NULL);
        pthread_cond_init(&workers[i].cv, NULL);
        workers[i].cmd = 0;
        pthread_create(&workers[i].th, NULL, worker_fn, &workers[i]);
    }
}

static void dispatch(job_t *jobs) {
    for (int i = 0; i < nthreads; i++) {
        pthread_mutex_lock(&workers[i].mu);
        workers[i].job = jobs[i];
        workers[i].cmd = 1;
        pthread_cond_signal(&workers[i].cv);
        pthread_mutex_unlock(&workers[i].mu);
    }
    for (int i = 0; i < nthreads; i++) {
        pthread_mutex_lock(&workers[i].mu);
        while (workers[i].cmd != 0) pthread_cond_wait(&workers[i].cv, &workers[i].mu);
        jobs[i].ghash_acc = workers[i].job.ghash_acc;
        pthread_mutex_unlock(&workers[i].mu);
    }
}

int main() {
    uint8_t key[16] = {0};
    set_key(key);
    size_t N = 60000*1024;
    size_t nblocks = N/16;
    uint8_t *pt = aligned_alloc(64, N);
    uint8_t *ct = aligned_alloc(64, N);
    memset(pt, 0x5a, N);
    pool_init();

    __m128i bswap = _mm_loadu_si128((const __m128i*)BSWAP);
    uint8_t iv[16] = {0}; iv[15] = 2;
    __m128i ctr0 = _mm_loadu_si128((const __m128i*)iv);

    for (int gh = 0; gh <= 1; gh++) {
        job_t jobs[MAX_THREADS];
        size_t per = (nblocks / nthreads);
        for (int i = 0; i < nthreads; i++) {
            jobs[i].pt = pt; jobs[i].ct = ct;
            jobs[i].start_block = i * per;
            jobs[i].nblocks = (i == nthreads-1) ? (nblocks - i*per) : per;
            __m128i ctr_le = _mm_add_epi32(_mm_shuffle_epi8(ctr0, bswap), _mm_set_epi32(0,0,0,(int)jobs[i].start_block));
            jobs[i].ctr0 = _mm_shuffle_epi8(ctr_le, bswap);
            jobs[i].do_ghash = gh;
        }
        dispatch(jobs);
        struct timespec t0, t1;
        int iters = 4;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int it = 0; it < iters; it++) dispatch(jobs);
        clock_gettime(CLOCK_MONOTONIC, &t1);
        double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
        printf("%s %d thr: %.2f ms\n", gh ? "CTR+GHASH" : "CTR only", nthreads, dt/iters*1000);
    }
    return 0;
}
