#include <tmmintrin.h>

/* 4-way aggregated GHASH: acc = ((((b0*H^4 + b1)*H^4 + b2)*H^4 + b3)*H^4 ...)
   Each step: acc = (acc XOR b_i) * H^4, computed for 4 independent streams,
   then combined. Here we just measure the multiply throughput of 4-way pclmul. */

static inline __m128i gmul(__m128i a, __m128i h, __m128i hx) {
    __m128i as = _mm_xor_si128(_mm_shuffle_epi32(a, 0x4e), a);
    __m128i c = _mm_clmulepi64_si128(a, h, 0x00);
    __m128i d = _mm_clmulepi64_si128(a, h, 0x11);
    __m128i e = _mm_clmulepi64_si128(as, hx, 0x00);
    e = _mm_xor_si128(e, _mm_xor_si128(c, d));
    c = _mm_xor_si128(c, _mm_slli_si128(e, 8));
    d = _mm_xor_si128(d, _mm_srli_si128(e, 8));
    __m128i t1 = _mm_slli_epi64(c, 57);
    __m128i t2 = _mm_slli_epi64(c, 62);
    __m128i t3 = _mm_slli_epi64(c, 63);
    __m128i t = _mm_xor_si128(t1, _mm_xor_si128(t2, t3));
    c = _mm_xor_si128(c, _mm_slli_si128(t, 8));
    d = _mm_xor_si128(d, _mm_srli_si128(t, 8));
    t1 = _mm_srli_epi64(c, 1);
    t2 = _mm_srli_epi64(c, 2);
    t3 = _mm_srli_epi64(c, 7);
    return _mm_xor_si128(d, _mm_xor_si128(c, _mm_xor_si128(t1, _mm_xor_si128(t2, t3))));
}

static void ghash4(const uint8_t *data, size_t nblocks, __m128i h, __m128i hx) {
    __m128i a0=_mm_setzero_si128(), a1=_mm_setzero_si128(), a2=_mm_setzero_si128(), a3=_mm_setzero_si128();
    size_t i = 0;
    for (; i + 4 <= nblocks; i += 4) {
        __m128i b0 = _mm_loadu_si128((const __m128i*)(data + (i+0)*16));
        __m128i b1 = _mm_loadu_si128((const __m128i*)(data + (i+1)*16));
        __m128i b2 = _mm_loadu_si128((const __m128i*)(data + (i+2)*16));
        __m128i b3 = _mm_loadu_si128((const __m128i*)(data + (i+3)*16));
        a0 = gmul(_mm_xor_si128(a0, b0), h, hx);
        a1 = gmul(_mm_xor_si128(a1, b1), h, hx);
        a2 = gmul(_mm_xor_si128(a2, b2), h, hx);
        a3 = gmul(_mm_xor_si128(a3, b3), h, hx);
    }
    volatile __m128i sink = _mm_xor_si128(_mm_xor_si128(a0,a1), _mm_xor_si128(a2,a3));
    (void)sink;
}

int main() {
    size_t N = 60000*1024, nblocks = N/16;
    uint8_t *data = aligned_alloc(64, N);
    memset(data, 0x5a, N);
    __m128i h = _mm_set_epi64x(0x123456789abcdef0LL, 0x0fedcba987654321LL);
    __m128i hx = _mm_xor_si128(h, _mm_shuffle_epi32(h, 0x4e));
    ghash4(data, nblocks, h, hx);
    struct timespec t0, t1;
    int iters = 3;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int i = 0; i < iters; i++) ghash4(data, nblocks, h, hx);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
    printf("4-way GHASH 60MB: %.2f ms\n", dt/iters*1000);
    return 0;
}
