#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <openssl/evp.h>

#define K 4
#define N (60000*1024)

extern void gcm_init_avx(void *Htable, const void *H);
extern void gcm_ghash_avx(uint8_t Xi[16], const void *Htable, const uint8_t *in, size_t len);

typedef struct {
    pthread_t th;
    pthread_mutex_t mu;
    pthread_cond_t cv;
    int cmd;
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *ctr;
    uint8_t key[16];
    uint8_t iv[16];
    const uint8_t *pt;
    uint8_t *out;
    size_t len;
    uint8_t Htable[16*32];
    uint8_t Xi[16];
    int do_ghash;
} worker_t;

static worker_t W[K];

static void *fn(void *arg) {
    worker_t *w = arg;
    pthread_mutex_lock(&w->mu);
    for (;;) {
        while (w->cmd == 0) pthread_cond_wait(&w->cv, &w->mu);
        if (w->cmd == 2) { pthread_mutex_unlock(&w->mu); return NULL; }
        pthread_mutex_unlock(&w->mu);

        int outl = 0, fl = 0;
        EVP_EncryptInit_ex(w->ctx, w->ctr, NULL, NULL, NULL);
        EVP_EncryptInit_ex(w->ctx, NULL, NULL, w->key, w->iv);
        EVP_EncryptUpdate(w->ctx, w->out, &outl, w->pt, (int)w->len);
        EVP_EncryptFinal_ex(w->ctx, w->out + outl, &fl);
        if (w->do_ghash) {
            memset(w->Xi, 0, 16);
            gcm_ghash_avx(w->Xi, w->Htable, w->out, w->len);
        }

        pthread_mutex_lock(&w->mu);
        w->cmd = 0;
        pthread_cond_signal(&w->cv);
    }
}

static void dispatch(void) {
    for (int i = 0; i < K; i++) {
        pthread_mutex_lock(&W[i].mu);
        W[i].cmd = 1;
        pthread_cond_signal(&W[i].cv);
        pthread_mutex_unlock(&W[i].mu);
    }
    for (int i = 0; i < K; i++) {
        pthread_mutex_lock(&W[i].mu);
        while (W[i].cmd != 0) pthread_cond_wait(&W[i].cv, &W[i].mu);
        pthread_mutex_unlock(&W[i].mu);
    }
}

int main(void) {
    const EVP_CIPHER *ctr = EVP_CIPHER_fetch(NULL, "AES-128-CTR", NULL);
    uint8_t *pt = aligned_alloc(64, N);
    uint8_t *out = aligned_alloc(64, N);
    memset(pt, 0x5a, N);
    uint8_t key[16] = {0};
    uint8_t H[16]; memset(H, 0x3c, 16);
    size_t chunk = N / K;
    for (int i = 0; i < K; i++) {
        memset(&W[i], 0, sizeof W[i]);
        pthread_mutex_init(&W[i].mu, NULL);
        pthread_cond_init(&W[i].cv, NULL);
        W[i].ctx = EVP_CIPHER_CTX_new();
        W[i].ctr = ctr;
        memcpy(W[i].key, key, 16);
        memset(W[i].iv, 0, 16);
        W[i].iv[15] = (uint8_t)(2 + i * (chunk/16));
        W[i].pt = pt + i*chunk;
        W[i].out = out + i*chunk;
        W[i].len = chunk;
        gcm_init_avx(W[i].Htable, H);
        pthread_create(&W[i].th, NULL, fn, &W[i]);
    }

    for (int gh = 0; gh <= 1; gh++) {
        for (int i = 0; i < K; i++) W[i].do_ghash = gh;
        dispatch();
        struct timespec t0, t1;
        int iters = 5;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        for (int it = 0; it < iters; it++) dispatch();
        clock_gettime(CLOCK_MONOTONIC, &t1);
        double dt = (t1.tv_sec - t0.tv_sec) + (t1.tv_nsec - t0.tv_nsec)/1e9;
        printf("%s: %.2f ms\n", gh ? "CTR+GHASH" : "CTR only", dt/iters*1000);
    }
    return 0;
}
